<?php

declare(strict_types=1);

namespace RageKit\Cli\Build\Steps;

use RageKit\Cli\Build\BuildContext;
use RageKit\Cli\Build\Step;
use Symfony\Component\Yaml\Yaml;

/** Writes the merged config as build/<backend>/tpc.yml, the file tpc compiles. */
final class WriteTpcConfig implements Step
{
    public function name(): string
    {
        return 'Write tpc.yml';
    }

    public function run(BuildContext $context): string
    {
        file_put_contents(
            $context->tpcConfigFile(),
            "# Generated by ragekit from project.yml + {$context->backend->file}. Do not edit.\n"
                . Yaml::dump($context->config, 4, 2),
        );
        return $context->relative($context->tpcConfigFile());
    }
}
